ARMS = 200

DIRS = ["stylesheets", "javascripts", "images", "fonts"]
EXTS = ["css", "js", "png", "woff2"]

def logical_name(i)
  d = i % 4
  "#{DIRS[d]}/asset_#{format("%03d", i)}.#{EXTS[d]}"
end

names = []
i = 0
while i < ARMS
  names << logical_name(i)
  i += 1
end
hits = 0
names.each { |n| hits += 1 unless Gen::Assets.digested(n).empty? }
puts "arms: #{ARMS}, hits: #{hits}, miss: #{Gen::Assets.digested("missing.css").inspect}"
puts "first: #{Gen::Assets.digested(names[0])}"
puts "last: #{Gen::Assets.digested(names[names.size - 1])}"
rounds = 5000
t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
total = 0
r = 0
while r < rounds
  names.each { |n| total += Gen::Assets.digested(n).bytesize }
  r += 1
end
t1 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
lookups = rounds * names.size
puts "#{lookups} lookups: #{((t1 - t0) * 1_000_000_000 / lookups).round} ns each (#{total} bytes)"
